package de.mika.promptwerk;
import android.content.*;import android.app.*;import android.app.job.*;import android.net.Uri;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
final class DriveSync {
 static final Object LOCK=new Object();static final AtomicBoolean running=new AtomicBoolean(),foreground=new AtomicBoolean();static final int PERIODIC=7311,SOON=7312;
 static File directory(Context c){File f=new File(c.getFilesDir(),"personal-sync");f.mkdirs();return f;}
 static JSONObject state(Context c,String owner)throws Exception{if(!owner.matches("[a-f0-9]{64}"))throw new IOException("Google-Kennung ungültig");File f=new File(directory(c),owner+".json");if(!f.isFile())return new JSONObject().put("protocol",2).put("records",new JSONObject()).put("files",new JSONObject());try(InputStream in=new FileInputStream(f)){JSONObject s=new JSONObject(new String(DriveHttp.read(in,25*1024*1024),StandardCharsets.UTF_8));if(s.optInt("protocol")<2){JSONObject records=s.getJSONObject("records");Iterator<String> it=records.keys();while(it.hasNext()){JSONObject r=records.getJSONObject(it.next());if(r.optBoolean("deleted")&&!r.optBoolean("deleteConfirmed")){r.put("deleted",false).put("dirty",true).put("base",0);r.remove("flight");}else if(r.optBoolean("dirty")&&!r.has("flight"))r.put("base",0);}s.put("protocol",2).put("bootstrapLocalPending",true);}return s;}}
 static void write(Context c,String owner,JSONObject s)throws Exception{File target=new File(directory(c),owner+".json"),tmp=new File(target.getPath()+".tmp");try(OutputStream out=new FileOutputStream(tmp)){out.write(s.toString().getBytes(StandardCharsets.UTF_8));}if(!tmp.renameTo(target))throw new IOException("Lokaler Syncstand nicht gespeichert");}
 static JSONObject connection(Context c){try{return DriveVault.read(c);}catch(Exception e){status(c,"Google Drive bitte erneut verbinden");return null;}}
 static void status(Context c,String text){c.getSharedPreferences("personal-drive-status",0).edit().putString("message",text).apply();}
 static String status(Context c){return c.getSharedPreferences("personal-drive-status",0).getString("message","Noch nicht mit Google Drive verbunden");}
 static String autoOwner(Context c){JSONObject auth=connection(c);return auth!=null&&auth.has("account")&&!auth.optBoolean("disconnectPending")?auth.optString("account"):"";}
 static void ensureExtras(Context c,String owner)throws Exception{android.content.SharedPreferences p=c.getSharedPreferences("library",0);if(p.getBoolean("driveExtras:"+owner,false))return;JSONObject e=DriveExtras.initial(new JSONObject(p.getString("ideas","{}")),new JSONArray(p.getString("parkedDrafts","[]")));DriveExtras.snapshot(e,owner);saveExtras(c,owner,e);if(!p.edit().putBoolean("driveExtras:"+owner,true).putString("ideas","{}").putString("parkedDrafts","[]").commit())throw new IOException("Automatischer Sync konnte nicht lokal aktiviert werden");}
 static void markAuto(MainActivity a)throws Exception{String owner=autoOwner(a);if(owner.isEmpty())return;synchronized(LOCK){ensureExtras(a,owner);for(MainActivity.Item item:a.items){if(!item.cloudOwner.isEmpty()&&!owner.equals(item.cloudOwner))continue;item.cloud=true;item.cloudOwner=owner;for(MainActivity.Att f:item.files)f.sync=true;}}}
 static String extraKey(Context c,String name){JSONObject auth=connection(c);if(auth!=null&&auth.has("account")){String owner=auth.optString("account");if(c.getSharedPreferences("library",0).getBoolean("driveExtras:"+owner,false))return name+":"+owner;}return name;}
 static JSONObject extras(Context c,String owner)throws Exception{android.content.SharedPreferences p=c.getSharedPreferences("library",0);return new JSONObject().put("ideas",new JSONObject(p.getString("ideas:"+owner,"{}"))).put("parked",new JSONArray(p.getString("parkedDrafts:"+owner,"[]"))).put("ids",new JSONObject(p.getString("extraIds:"+owner,"{}")));}
 static void saveExtras(Context c,String owner,JSONObject e)throws Exception{if(!c.getSharedPreferences("library",0).edit().putString("ideas:"+owner,e.getJSONObject("ideas").toString()).putString("parkedDrafts:"+owner,e.getJSONArray("parked").toString()).putString("extraIds:"+owner,e.getJSONObject("ids").toString()).commit())throw new IOException("Ideen/Entwürfe nicht gespeichert");}
 static JSONArray withExtras(Context c,JSONArray items,String owner)throws Exception{JSONArray all=new JSONArray(items.toString());if(c.getSharedPreferences("library",0).getBoolean("driveExtras:"+owner,false)){JSONObject e=extras(c,owner);JSONArray notes=DriveExtras.snapshot(e,owner);saveExtras(c,owner,e);for(int n=0;n<notes.length();n++)all.put(notes.getJSONObject(n));}return all;}
 static void capture(Context c,JSONArray items){JSONObject auth=connection(c);if(auth==null||!auth.has("account")||auth.optBoolean("disconnectPending"))return;try{synchronized(LOCK){String owner=auth.getString("account");JSONObject s=state(c,owner);ensureExtras(c,owner);DriveMerge.capture(s.getJSONObject("records"),withExtras(c,DriveMerge.completeCollection(items,owner),owner),owner);write(c,owner,s);}schedule(c);}catch(Exception e){status(c,"Syncwarteschlange nicht gespeichert: "+e.getMessage());}}
 static void deleteConfirmed(MainActivity a,String id)throws Exception{String owner=autoOwner(a);if(owner.isEmpty())return;synchronized(LOCK){JSONObject s=state(a,owner);DriveMerge.deleteConfirmed(s.getJSONObject("records"),id);write(a,owner,s);}schedule(a);}
 static void schedule(Context c){if(connection(c)==null)return;try{JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);ComponentName service=new ComponentName(c,DriveSyncJob.class);jobs.schedule(new JobInfo.Builder(PERIODIC,service).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPersisted(true).setPeriodic(15*60*1000L).build());jobs.schedule(new JobInfo.Builder(SOON,service).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setMinimumLatency(3000).build());}catch(Exception e){status(c,"Automatischer Hintergrundabgleich nicht verfügbar; bei geöffneter App erneut versuchen");}}
 static void begin(MainActivity a){JSONObject pendingDisconnect=connection(a);if(pendingDisconnect!=null&&pendingDisconnect.optBoolean("disconnectPending")){a.toast("Bitte zuerst den ausstehenden Gerätewiderruf abschließen");return;}new AlertDialog.Builder(a).setTitle("Dein persönliches Google Drive").setMessage("Verbinde dein eigenes Google-Konto. Nach dieser bewussten Verbindung werden dein eigener Bestand und alle neuen Prompts, Bausteine, Projektideen, geparkten Entwürfe und Anlagen automatisch mit deinem privaten Drive abgeglichen. Änderungen werden ohne weitere Nachfrage übertragen; Löschen verlangt zuvor eine Bestätigung. Der Systembrowser öffnet die Google-Kontoauswahl. Lokales Speichern bleibt möglich.").setNegativeButton("Abbrechen",null).setPositiveButton("Google-Konto verbinden",(d,w)->new Thread(()->{try{String verifier=base64(random(48)),challenge=base64(java.security.MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));JSONObject response=DriveHttp.json("google-device.php","POST",new JSONObject().put("action","begin").put("challenge",challenge),null);JSONObject previous=connection(a);JSONObject pending=(previous==null?new JSONObject():new JSONObject(previous.toString())).put("pair",response.getString("pair")).put("verifier",verifier).put("pendingUntil",System.currentTimeMillis()+600000);DriveVault.write(a,pending);String url=response.getString("url");if(!url.startsWith("https://gsgev.org/promptwerk/google-connect.php?pair="))throw new IOException("Ungültiges Verbindungsziel");a.runOnUiThread(()->a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url))));}catch(Exception e){a.runOnUiThread(()->a.toast(e.getMessage()));}}).start()).show();}
 static byte[] random(int n){byte[] b=new byte[n];new java.security.SecureRandom().nextBytes(b);return b;}static String base64(byte[] b){return android.util.Base64.encodeToString(b,android.util.Base64.URL_SAFE|android.util.Base64.NO_WRAP|android.util.Base64.NO_PADDING);}
 static void resume(MainActivity a){if(!foreground.compareAndSet(false,true))return;final JSONArray localSnapshot;try{markAuto(a);synchronized(LOCK){String owner=autoOwner(a);if(!owner.isEmpty()){JSONObject s=state(a,owner);if(s.optBoolean("bootstrapLocalPending")){DriveMerge.capture(s.getJSONObject("records"),withExtras(a,DriveMerge.completeCollection(a.data(),owner),owner),owner);s.remove("bootstrapLocalPending");write(a,owner,s);}}}apply(a);localSnapshot=a.data();if(!a.prefs.edit().putString("items",localSnapshot.toString()).commit())throw new IOException("Lokaler Syncstand nicht gespeichert");capture(a,localSnapshot);}catch(Exception e){status(a,"Sammlung konnte nicht für Sync gelesen werden");foreground.set(false);return;}new Thread(()->{try{JSONObject auth=connection(a);if(auth==null)return;if(auth.has("pair")){if(auth.optLong("pendingUntil")<System.currentTimeMillis()){status(a,"Google-Verbindung abgelaufen; bitte erneut beginnen");return;}for(int i=0;i<20;i++){JSONObject result=DriveHttp.json("google-device.php","POST",new JSONObject().put("action","finish").put("pair",auth.getString("pair")).put("verifier",auth.getString("verifier")),null);if(!result.optBoolean("pending")){DriveVault.write(a,new JSONObject().put("token",result.getString("token")).put("email",result.getString("email")).put("account",result.getString("account")));status(a,"Verbunden mit "+result.getString("email"));break;}Thread.sleep(1500);}}
  synchronize(a);a.runOnUiThread(()->apply(a));schedule(a);
 }catch(Exception e){status(a,"Sync wartet: "+e.getMessage());}finally{foreground.set(false);}}).start();}
 static void synchronize(Context c)throws Exception{if(!running.compareAndSet(false,true))return;try{JSONObject auth=connection(c);if(auth==null||!auth.has("account"))return;if(auth.optBoolean("disconnectPending")){finishDisconnect(c,auth);return;}String owner=auth.getString("account"),token=auth.getString("token");JSONObject response=DriveHttp.json("google-sync.php","GET",null,token);if(!owner.equals(response.getString("account")))throw new IOException("Google-Konto stimmt nicht mit lokalem Syncstand überein");
  synchronized(LOCK){JSONObject s=state(c,owner);DriveMerge.pull(s.getJSONObject("records"),response.getJSONObject("document"),owner);s.put("files",response.getJSONObject("document").getJSONObject("files"));write(c,owner,s);}
  JSONObject snapshot; synchronized(LOCK){snapshot=state(c,owner);}
  JSONObject records=snapshot.getJSONObject("records");Iterator<String> ids=records.keys();while(ids.hasNext()){if(Thread.currentThread().isInterrupted())throw new InterruptedException();String id=ids.next();JSONObject queued=records.getJSONObject(id);if((!queued.optBoolean("dirty")&&!queued.has("flight"))||queued.optBoolean("excluded"))continue;JSONObject flight;synchronized(LOCK){JSONObject saved=state(c,owner);JSONObject actual=saved.getJSONObject("records").optJSONObject(id);if(actual==null)continue;flight=DriveMerge.copy(DriveMerge.startFlight(actual));write(c,owner,saved);}JSONObject e=flight.getJSONObject("entry");
   if(!flight.optBoolean("deleted")){JSONArray attachments=e.optJSONArray("files");if(attachments!=null)for(int n=0;n<attachments.length();n++){JSONObject f=attachments.getJSONObject(n);if(!f.optBoolean("sync"))continue;String key=f.getString("key");if(snapshot.getJSONObject("files").has(key))continue;File file=new File(c.getFilesDir(),"attachments/"+key);if(!file.isFile())throw new IOException("Anlage fehlt auf diesem Gerät: "+f.getString("name"));if(file.length()>10485760)throw new IOException("Driveanlage größer als 10 MiB: "+f.getString("name"));byte[] bytes;try(InputStream in=new FileInputStream(file)){bytes=DriveHttp.read(in,25*1024*1024);}if(!DriveMerge.sha(bytes).equals(key))throw new IOException("Anlage ist beschädigt");JSONObject saved=new JSONObject(new String(DriveHttp.request("google-sync.php?action=upload","PUT",bytes,token,f.getString("name")),StandardCharsets.UTF_8));snapshot.getJSONObject("files").put(key,saved.getJSONObject("file"));}}
   JSONObject change=new JSONObject().put("action",flight.optBoolean("deleted")?"delete":"save").put("id",id).put("base",flight.optInt("base")).put("operation",flight.getString("operation"));if(!flight.optBoolean("deleted"))change.put("entry",DriveMerge.wire(e));JSONObject result=DriveHttp.json("google-sync.php","POST",change,token);
   synchronized(LOCK){JSONObject saved=state(c,owner);String notice=DriveMerge.acknowledge(saved.getJSONObject("records"),id,result,owner);if(!notice.isEmpty())saved.put("notice",notice);write(c,owner,saved);}

  }
  response=DriveHttp.json("google-sync.php","GET",null,token);synchronized(LOCK){JSONObject s=state(c,owner);DriveMerge.pull(s.getJSONObject("records"),response.getJSONObject("document"),owner);s.put("files",response.getJSONObject("document").getJSONObject("files"));write(c,owner,s);}
  downloadMissing(c,owner,token);String notice; synchronized(LOCK){notice=state(c,owner).optString("notice");}status(c,(notice.isEmpty()?"":notice+"\n\n")+"Mit "+auth.getString("email")+" synchronisiert");
 }finally{running.set(false);}}
 static void downloadMissing(Context c,String owner,String token)throws Exception{JSONObject s; synchronized(LOCK){s=state(c,owner);}JSONObject records=s.getJSONObject("records");Iterator<String> ids=records.keys();while(ids.hasNext()){JSONObject r=records.getJSONObject(ids.next());if(r.optBoolean("deleted")||r.optBoolean("excluded"))continue;JSONArray files=r.getJSONObject("entry").optJSONArray("files");if(files==null)continue;for(int n=0;n<files.length();n++){JSONObject f=files.getJSONObject(n);if(!f.optBoolean("sync"))continue;String key=f.getString("key");File target=new File(c.getFilesDir(),"attachments/"+key);if(target.isFile())continue;byte[] bytes=DriveHttp.request("google-file.php?id="+key,"GET",null,token,null);if(bytes.length>10485760||!DriveMerge.sha(bytes).equals(key))throw new IOException("Driveanlage nicht bestätigt");target.getParentFile().mkdirs();File tmp=new File(target.getPath()+".sync");try(OutputStream out=new FileOutputStream(tmp)){out.write(bytes);}if(!tmp.renameTo(target))throw new IOException("Anlage nicht lokal gespeichert");}}}
 static void apply(MainActivity a){JSONObject auth=connection(a);if(auth==null||!auth.has("account")||auth.optBoolean("disconnectPending")||a.entryWindow!=null||a.ideaPadOpen||a.busy)return;try{String owner=auth.getString("account");markAuto(a);synchronized(LOCK){JSONObject s=state(a,owner),records=s.getJSONObject("records");Iterator<String> ids=records.keys();while(ids.hasNext()){String id=ids.next();JSONObject r=records.getJSONObject(id);if(r.optBoolean("dirty")||r.has("flight")||r.optBoolean("excluded"))continue;if(DriveExtras.extra(r.getJSONObject("entry"))){JSONObject extra=extras(a,owner);DriveExtras.apply(extra,r);saveExtras(a,owner,extra);if(!a.prefs.edit().putBoolean("driveExtras:"+owner,true).commit())throw new IOException("Syncbereich nicht gespeichert");r.put("seenLocal",true).put("localContent",DriveMerge.content(r.getJSONObject("entry"))).put("localBase",r.optInt("base"));continue;}MainActivity.Item existing=null;for(MainActivity.Item i:a.items)if(i.id.equals(id)){existing=i;break;}if(existing!=null&&(!existing.cloud||!owner.equals(existing.cloudOwner)))continue;if(r.optBoolean("deleted")){if(existing!=null)a.items.remove(existing);continue;}MainActivity.Item imported=a.parse(r.getJSONObject("entry"));if(existing!=null)a.items.set(a.items.indexOf(existing),imported);else a.items.add(imported);r.put("seenLocal",true).put("localContent",DriveMerge.content(r.getJSONObject("entry"))).put("localBase",r.optInt("base"));}write(a,owner,s);a.prefs.edit().putString("items",a.data().toString()).commit();}a.render();}catch(Exception e){status(a,"Drivebestand konnte nicht übernommen werden: "+e.getMessage());}}
 static HashSet<String> referencedFiles(Context c){HashSet<String> keys=new HashSet<>();try{synchronized(LOCK){File[] accounts=directory(c).listFiles();if(accounts==null)throw new IOException("Syncablage nicht lesbar");for(File file:accounts){String name=file.getName();if(!name.matches("[a-f0-9]{64}\\.json"))continue;JSONObject records=state(c,name.substring(0,64)).getJSONObject("records");Iterator<String> ids=records.keys();while(ids.hasNext()){JSONObject r=records.getJSONObject(ids.next());for(JSONObject entry:new JSONObject[]{r.optJSONObject("entry"),r.optJSONObject("flight")==null?null:r.getJSONObject("flight").optJSONObject("entry")}){if(entry==null)continue;JSONArray files=entry.optJSONArray("files");if(files!=null)for(int n=0;n<files.length();n++)keys.add(files.getJSONObject(n).getString("key"));}}}}}catch(Exception e){return null;}return keys;}
 static void finishDisconnect(Context c,JSONObject auth)throws Exception{
  try{DriveHttp.json("google-sync.php","POST",new JSONObject().put("action","disconnect"),auth.getString("token"));}catch(DriveHttp.HttpError e){if(e.status!=401)throw e;}
  synchronized(LOCK){JSONObject current=connection(c);if(current==null||!current.optString("token").equals(auth.optString("token")))return;DriveVault.clear(c);}
  JobScheduler jobs=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);jobs.cancel(PERIODIC);jobs.cancel(SOON);status(c,"Gerätezugang auf dem Server widerrufen. Andere Geräte und Drive-Dateien bleiben erhalten.");
 }
 static void disconnect(MainActivity a){new Thread(()->{try{JSONObject auth=connection(a);if(auth==null||!auth.has("account"))return;
  synchronized(LOCK){JSONObject rows=state(a,auth.getString("account")).getJSONObject("records");Iterator<String> it=rows.keys();while(it.hasNext()){JSONObject row=rows.getJSONObject(it.next());if(!row.optBoolean("excluded")&&(row.optBoolean("dirty")||row.has("flight")))throw new IOException("Noch nicht synchronisierte Änderungen vorhanden. Bitte zuerst synchronisieren oder lokal sichern.");}auth.put("disconnectPending",true);DriveVault.write(a,auth);}
  status(a,"Lokal getrennt. Serverwiderruf wird bestätigt; bei fehlendem Netz wird er nachgeholt.");schedule(a);
  try{finishDisconnect(a,auth);a.runOnUiThread(()->a.toast("Gerätezugang auf dem Server widerrufen"));}catch(Exception e){status(a,"Lokal getrennt; Serverwiderruf wartet auf Internet. Andere Syncaktionen sind bis dahin gesperrt.");a.runOnUiThread(()->a.toast("Widerruf wird bei Internetverbindung nachgeholt"));}
 }catch(Exception e){a.runOnUiThread(()->a.toast(e.getMessage()));}}).start();}
 static void includeAll(MainActivity a){
  JSONObject auth=connection(a);if(auth==null||!auth.has("account")||auth.optBoolean("disconnectPending")){a.toast("Bitte zuerst dein Google Drive verbinden");return;}
  String owner=auth.optString("account");
  new AlertDialog.Builder(a).setTitle("Gesamten Bestand synchronisieren").setMessage("Alle lokalen Prompts und Bausteine einschließlich Erledigter, Favoriten, Projekte, Projektideen, geparkter Entwürfe und zugehöriger Anlagen mit "+auth.optString("email")+" synchronisieren? Einträge anderer Google-Konten bleiben getrennt. Der ungespeicherte Entwurf bleibt auf diesem Gerät.").setNegativeButton("Abbrechen",null).setPositiveButton("Bestand synchronisieren",(d,w)->{
   JSONObject current=connection(a);if(current==null||!owner.equals(current.optString("account"))||current.optBoolean("disconnectPending")){a.toast("Google-Konto gewechselt; bitte erneut beginnen");return;}
   try{boolean wasEnabled=a.prefs.getBoolean("driveExtras:"+owner,false);if(!wasEnabled){JSONObject extra=DriveExtras.initial(new JSONObject(a.prefs.getString("ideas","{}")),new JSONArray(a.prefs.getString("parkedDrafts","[]")));DriveExtras.snapshot(extra,owner);saveExtras(a,owner,extra);if(!a.prefs.edit().putBoolean("driveExtras:"+owner,true).commit())throw new IOException("Gesamtbestand nicht gespeichert");}JSONArray prepared=DriveMerge.completeCollection(a.data(),owner);ArrayList<MainActivity.Item> before=new ArrayList<>(a.items),next=new ArrayList<>();for(int n=0;n<prepared.length();n++)next.add(a.parse(prepared.getJSONObject(n)));a.items.clear();a.items.addAll(next);if(!a.persist()){a.items.clear();a.items.addAll(before);if(!wasEnabled)a.prefs.edit().putBoolean("driveExtras:"+owner,false).commit();return;}a.render();resume(a);a.toast("Gesamtbestand für Drive-Sync vorgemerkt");}catch(Exception e){a.toast("Übernahme nicht gespeichert: "+e.getMessage());}
  }).show();
 }
 static void menu(MainActivity a){JSONObject auth=connection(a);boolean revoking=auth!=null&&auth.optBoolean("disconnectPending");String email=auth==null?"Nicht verbunden":auth.optString("email","Anmeldung begonnen");new AlertDialog.Builder(a).setTitle("Mein Google Drive").setMessage(email+"\n\n"+status(a)+"\n\nAutomatischer Sync ist mit der bewussten Verbindung aktiv: Neue Inhalte und Änderungen werden ohne Rückfrage abgeglichen. Löschungen müssen zuvor bestätigt werden. Android kann Hintergrundarbeit verzögern. Gerät trennen widerruft nur diesen Gerätezugang. Ein vollständiger Google-Widerruf erfolgt in den Google-Kontoberechtigungen.").setPositiveButton(revoking?"Widerruf nachholen":auth!=null&&auth.has("account")?"Jetzt synchronisieren":"Google-Konto verbinden",(d,w)->{if(auth!=null&&auth.has("account"))resume(a);else begin(a);}).setNeutralButton("Dieses Gerät trennen",(d,w)->disconnect(a)).setNegativeButton(revoking?"Schließen":"Google-Konto neu verbinden",(d,w)->{if(!revoking)begin(a);}).show();}
}
